      a,
      button {
        font: inherit;
      }

      :focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 4px;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        padding: 0.75rem 1rem;
        color: #ffffff;
        background: #111827;
        border-radius: 999px;
        transform: translateY(-150%);
        transition: transform 160ms ease;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .site-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        width: min(1120px, calc(100% - 2rem));
        margin: 0 auto;
        padding: 1.5rem 0;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.75rem;
        margin: 0;
        font-size: 1rem;
        font-weight: 800;
      }

      .brand-mark {
        display: grid;
        width: 2.25rem;
        height: 2.25rem;
        place-items: center;
        color: #ffffff;
        background: linear-gradient(135deg, #1d4ed8, #0f172a);
        border-radius: 0.8rem;
      }

      .library-link {
        color: var(--primary);
        font-weight: 700;
        text-decoration: none;
      }

      .library-link:hover {
        text-decoration: underline;
      }

      main {
        width: min(1120px, calc(100% - 2rem));
        margin: 0 auto;
        padding: clamp(1rem, 4vw, 3rem) 0 4rem;
      }

      .preview-shell {
        display: grid;
        grid-template-columns: minmax(0, 1.15fr) minmax(18rem, 0.85fr);
        gap: clamp(1.25rem, 4vw, 3rem);
        align-items: center;
      }

      .image-card,
      .details-card {
        background: rgba(255, 255, 255, 0.86);
        border: 1px solid rgba(217, 225, 236, 0.8);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow);
        backdrop-filter: blur(14px);
      }

      .image-card {
        overflow: hidden;
      }

      .image-toolbar {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 1rem 1.25rem;
        border-bottom: 1px solid var(--border);
      }

      .eyebrow {
        margin: 0;
        color: var(--muted);
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      .pill {
        display: inline-flex;
        align-items: center;
        min-height: 2rem;
        padding: 0.25rem 0.75rem;
        color: #14532d;
        font-size: 0.88rem;
        font-weight: 800;
        background: #dcfce7;
        border-radius: 999px;
      }

      .photo {
        display: block;
        width: 100%;
        aspect-ratio: 4 / 3;
        object-fit: cover;
        background: #dbeafe;
      }

      .details-card {
        padding: clamp(1.25rem, 4vw, 2.25rem);
      }

      h1 {
        max-width: 11ch;
        margin: 0.5rem 0 1rem;
        font-size: clamp(2.3rem, 6vw, 4.7rem);
        line-height: 0.92;
        letter-spacing: -0.07em;
      }

      .lede {
        margin: 0 0 1.5rem;
        color: var(--muted);
        font-size: 1.08rem;
      }

      .metadata {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 0.75rem;
        margin: 0 0 1.75rem;
      }

      .meta-item {
        padding: 1rem;
        background: var(--surface-muted);
        border: 1px solid var(--border);
        border-radius: var(--radius-md);
      }

      .meta-item dt {
        margin: 0 0 0.25rem;
        color: var(--muted);
        font-size: 0.78rem;
        font-weight: 800;
        text-transform: uppercase;
      }

      .meta-item dd {
        margin: 0;
        font-weight: 800;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
      }

      .button {
        display: inline-flex;
        min-height: 2.75rem;
        align-items: center;
        justify-content: center;
        gap: 0.5rem;
        padding: 0.7rem 1rem;
        color: var(--text);
        font-weight: 800;
        background: #ffffff;
        border: 1px solid var(--border);
        border-radius: 999px;
        cursor: pointer;
        transition:
          transform 160ms ease,
          box-shadow 160ms ease,
          background-color 160ms ease;
      }

      .button:hover {
        transform: translateY(-1px);
        box-shadow: 0 12px 24px rgba(15, 23, 42, 0.1);
      }

      .button-primary {
        color: #ffffff;
        background: var(--primary);
        border-color: var(--primary);
      }

      .button-primary:hover {
        background: var(--primary-dark);
      }

      .button-danger {
        color: #ffffff;
        background: var(--danger);
        border-color: var(--danger);
      }

      .button-danger:hover {
        background: var(--danger-dark);
      }

      .status {
        min-height: 1.5rem;
        margin: 1rem 0 0;
        color: var(--danger);
        font-weight: 800;
      }

      dialog {
        width: min(92vw, 31rem);
        padding: 0;
        color: var(--text);
        background: var(--surface);
        border: 0;
        border-radius: 24px;
        box-shadow: 0 34px 90px rgba(15, 23, 42, 0.32);
      }

      dialog::backdrop {
        background: rgba(15, 23, 42, 0.56);
        backdrop-filter: blur(6px);
      }

      .dialog-panel {
        padding: clamp(1.25rem, 5vw, 2rem);
      }

      .dialog-icon {
        display: grid;
        width: 3rem;
        height: 3rem;
        margin-bottom: 1rem;
        place-items: center;
        color: var(--danger);
        background: #fee2e2;
        border-radius: 1rem;
      }

      .dialog-title {
        margin: 0 0 0.75rem;
        font-size: clamp(1.5rem, 5vw, 2rem);
        line-height: 1.05;
        letter-spacing: -0.04em;
      }

      .dialog-copy {
        margin: 0 0 1.5rem;
        color: var(--muted);
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: 0.75rem;
      }

      @media (max-width: 780px) {
        .preview-shell {
          grid-template-columns: 1fr;
        }

        .metadata {
          grid-template-columns: 1fr;
        }
      }

      @media (max-width: 460px) {
        .site-header {
          align-items: flex-start;
          flex-direction: column;
        }

        .actions,
        .dialog-actions {
          flex-direction: column;
        }

        .button {
          width: 100%;
        }
      }

      @media (prefers-reduced-motion: reduce) {
