        .map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
    };
  }

  const closed = await runAxe('closed');
  await page.click('.trigger');
  const open = await runAxe('open-dialog');
  await browser.close();

  const results = [closed, open];
  console.log(JSON.stringify(results, null, 2));
  const hasWcag = results.some(r => r.wcag.length);
  process.exit(hasWcag ? 1 : 0);
})().catch(error => {
  console.error(error.message);
  process.exit(2);
});
